const PREFIX =

    "aura";





/*
==========================================================
Cache Keys
==========================================================
*/

export class CacheKeys {

    /*
    ======================================================
    Application
    ======================================================
    */

    public application(): string {

        return `${PREFIX}:application`;

    }





    /*
    ======================================================
    Health
    ======================================================
    */

    public health(): string {

        return `${PREFIX}:health`;

    }





    /*
    ======================================================
    Market
    ======================================================
    */

    public market(

        pair: string,

    ): string {

        return `${PREFIX}:market:${pair.toLowerCase()}`;

    }





    /*
    ======================================================
    Order
    ======================================================
    */

    public order(

        orderId: string,

    ): string {

        return `${PREFIX}:order:${orderId}`;

    }





    /*
    ======================================================
    Portfolio
    ======================================================
    */

    public portfolio(

        accountId: string,

    ): string {

        return `${PREFIX}:portfolio:${accountId}`;

    }





    /*
    ======================================================
    Strategy
    ======================================================
    */

    public strategy(

        strategy: string,

    ): string {

        return `${PREFIX}:strategy:${strategy}`;

    }





    /*
    ======================================================
    Runtime
    ======================================================
    */

    public runtime(): string {

        return `${PREFIX}:runtime`;

    }





    /*
    ======================================================
    Metrics
    ======================================================
    */

    public metrics(): string {

        return `${PREFIX}:metrics`;

    }





    /*
    ======================================================
    Custom
    ======================================================
    */

    public custom(

        ...segments: string[]

    ): string {

        return [

            PREFIX,

            ...segments,

        ].join(":");

    }

}





/*
==========================================================
Singleton
==========================================================
*/

export const cacheKeys =

    new CacheKeys();
